(function(){"use strict";App.Managers={generatePassword:function(){var r;return r="aAbcdeEfghiJkmnpqrstuUvwxyz23456789",Array.apply(null,{length:12}).map(function(){var a;return a=Math.floor(Math.random()*r.length),r.charAt(a)}).join("")},togglePassword:function(a){$("#user_password").prop("type",a)},initialize:function(){$(".generate-random-value").on("click",function(){$("#user_password").val(App.Managers.generatePassword())}),$(".show-password").on("click",function(){$("#user_password").is("input[type='password']")?App.Managers.togglePassword("text"):App.Managers.togglePassword("password")})}}}).call(this);